var PHRASE_KEYS = Object.keys(PHRASES).sort(function(a,b){ return b.length-a.length; });
function rxEsc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
// Una sola pasada con alternancia (más larga primero): evita que una frase ya
// traducida vuelva a coincidir con una clave más corta (p. ej. "Velocidade"
// contiene "Velocidad" y terminaba dando "Velocidadee").
var PHRASE_RE = new RegExp(PHRASE_KEYS.map(rxEsc).join('|'), 'g');
var LANG = 'es';
try{ LANG = localStorage.getItem('ebp:lang') || 'es'; }catch(e){}
if(['es','en','pt'].indexOf(LANG)<0) LANG='es';
var NT0 = String.fromCharCode(0x2063), NT1 = String.fromCharCode(0x2064);
var NT_RE = new RegExp(NT0+'([^'+NT1+']*)'+NT1, 'g'), NT_STRIP = new RegExp("["+NT0+NT1+"]", "g");
function L3(es, en, pt){
  var t = LANG==='en' ? en : LANG==='pt' ? pt : es;
  return NT0 + String(t===undefined ? es : t).replace(NT_STRIP,'') + NT1;
}
function trPlain(str){
  if(LANG==='es') return str;
  var idx = LANG==='en' ? 0 : 1;
  return str.replace(PHRASE_RE, function(m){ var tr=PHRASES[m][idx]; return tr!==undefined?tr:m; });
}
function trHTML(str){
  if(str===null || str===undefined || str==='') return str;
  str = String(str);
  var out = '', last = 0, m;
  NT_RE.lastIndex = 0;
  while((m = NT_RE.exec(str))){ out += trPlain(str.slice(last, m.index)) + m[1]; last = NT_RE.lastIndex; }
  return (out + trPlain(str.slice(last))).replace(NT_STRIP,'');
}
function decSep(){ return LANG==='en' ? '.' : ','; }
// Número con d decimales en el formato del idioma (sin separador de miles)
function nf(v, d){ var s = Number(v).toFixed(d); return decSep()===',' ? s.replace('.', ',') : s; }
// Entero grande con separador de miles del idioma
function nInt(v){ try{ return Math.round(v).toLocaleString(LANG==='en'?'en-US':LANG==='pt'?'pt-BR':'es-AR'); }catch(e){ return String(Math.round(v)); } }
if(typeof setNumberFormatter==='function') setNumberFormatter(nf);


